import React, { useRef } from 'react'; 
import { useMountEffect } from 'primereact/hooks';
import { Messages } from 'primereact/messages';

export default function Sticky() {
    const msgs = useRef(null);

    useMountEffect(() => {
        if (msgs.current) {
            msgs.current.clear();
            msgs.current.show([
                { sticky: true, life: 1000, className: 'success', summary: 'Success', detail: 'Message Content', closable: false },
                { sticky: true, life: 2000, className: 'info', summary: 'Info', detail: 'Message Content', closable: false },
                { sticky: true, life: 3000, className: 'warn', summary: 'Warning', detail: 'Message Content', closable: false },
                { sticky: true, life: 4000, className: 'error', summary: 'Error', detail: 'Message Content', closable: false }
            ]);
        }
    });

    return (
        <div className="card">
            <Messages ref={msgs} />
        </div>
    )
}